const config = $('Set Config Variables').first().json;
const keyword = config.keyword.toLowerCase();
const sinceUnix = config.since_unix;
const sinceMs = sinceUnix * 1000;

let items = [];

const isRecent = (dateStr) => {
  if (!dateStr) return false;
  const ms = new Date(dateStr).getTime();
  return !isNaN(ms) && ms >= sinceMs;
};

// --- 1. arXiv ---
try {
  const raw = $('Fetch arXiv Papers').first().json;
  const xmlStr = raw.data || raw.body || JSON.stringify(raw);
  const entries = xmlStr.match(/<entry>(.*?)<\/entry>/gs) || [];
  entries.forEach(entry => {
    const title = (entry.match(/<title>(.*?)<\/title>/s)?.[1] || '').replace(/\n/g,' ').trim();
    const url = (entry.match(/<id>(.*?)<\/id>/s)?.[1] || '').trim();
    const excerpt = (entry.match(/<summary>(.*?)<\/summary>/s)?.[1] || '').replace(/\n/g,' ').trim().slice(0,500);
    const pubDate = (entry.match(/<published>(.*?)<\/published>/s)?.[1] || '').trim();
    if (title && url && isRecent(pubDate)) {
      items.push({ title, url, excerpt, source: 'arXiv', published_at: pubDate, source_weight: 90, engagement: 0 });
    }
  });
} catch(e) { console.log('arXiv err:', e.message); }

// --- 2. HackerNews ---
try {
  const hnData = $('Fetch Hacker News').first().json;
  (hnData.hits || []).forEach(h => {
    items.push({
      title: h.title || '',
      url: h.url || ('https://news.ycombinator.com/item?id=' + h.objectID),
      excerpt: (h.story_text || h.title || '').replace(/<[^>]+>/g,'').slice(0,400),
      source: 'HackerNews',
      published_at: new Date(h.created_at_i * 1000).toISOString(),
      source_weight: 75,
      engagement: h.points || 0
    });
  });
} catch(e) { console.log('HN err:', e.message); }

// --- 3. Reddit ---
try {
  const redditData = $('Fetch Reddit Posts').first().json;
  (redditData && redditData.data && redditData.data.children ? redditData.data.children : []).forEach(p => {
    const d = p.data;
    const pubDate = new Date(d.created_utc * 1000).toISOString();
    if (!isRecent(pubDate)) return;
    items.push({
      title: d.title || '',
      url: d.url || ('https://reddit.com' + d.permalink),
      excerpt: (d.selftext || d.title || '').slice(0,400),
      source: 'Reddit',
      published_at: pubDate,
      source_weight: 65,
      engagement: d.score || 0
    });
  });
} catch(e) { console.log('Reddit err:', e.message); }

// --- 4. GitHub ---
try {
  const ghData = $('Fetch GitHub Repos').first().json;
  (ghData.items || []).forEach(r => {
    if (!isRecent(r.created_at)) return;
    items.push({
      title: '[GitHub] ' + r.full_name + ': ' + (r.description || ''),
      url: r.html_url || '',
      excerpt: r.description || ('New GitHub repo about ' + keyword),
      source: 'GitHub',
      published_at: r.created_at,
      source_weight: 80,
      engagement: r.stargazers_count || 0
    });
  });
} catch(e) { console.log('GitHub err:', e.message); }

// --- 5. Google News ---
try {
  const gnData = $('Fetch Google News RSS').first().json;
  const xmlStr = gnData.data || gnData.body || JSON.stringify(gnData);
  const itemMatches = xmlStr.match(/<item>(.*?)<\/item>/gs) || [];
  itemMatches.forEach(item => {
    const titleM = item.match(/<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s);
    const linkM = item.match(/<link>(.*?)<\/link>/s);
    const descM = item.match(/<description>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s);
    const dateM = item.match(/<pubDate>(.*?)<\/pubDate>/s);
    const title = (titleM && titleM[1] ? titleM[1] : '').trim();
    const url = (linkM && linkM[1] ? linkM[1] : '').trim();
    const excerpt = (descM && descM[1] ? descM[1] : '').replace(/<[^>]+>/g,'').trim().slice(0,400);
    const pubDate = dateM ? new Date(dateM[1].trim()).toISOString() : '';
    if (title && url && isRecent(pubDate)) {
      items.push({ title, url, excerpt, source: 'GoogleNews', published_at: pubDate, source_weight: 60, engagement: 0 });
    }
  });
} catch(e) { console.log('GNews err:', e.message); }

// --- 6. NewsAPI ---
try {
  const naData = $('Fetch NewsAPI').first().json;
  (naData.articles || []).forEach(a => {
    if (!isRecent(a.publishedAt) || a.title === '[Removed]') return;
    items.push({
      title: a.title || '',
      url: a.url || '',
      excerpt: a.description || (a.content || '').slice(0,400),
      source: 'NewsAPI',
      published_at: a.publishedAt,
      source_weight: 70,
      engagement: 0
    });
  });
} catch(e) { console.log('NewsAPI err:', e.message); }

// --- 7. HuggingFace ---
try {
  const hfData = $('Fetch HuggingFace Papers RSS').first().json;
  const xmlStr = hfData.data || hfData.body || JSON.stringify(hfData);
  const itemMatches = xmlStr.match(/<item>(.*?)<\/item>/gs) || [];
  const kw0 = keyword.split(' ')[0];
  itemMatches.forEach(item => {
    const titleM = item.match(/<title>(.*?)<\/title>/s);
    const linkM = item.match(/<link>(.*?)<\/link>/s);
    const descM = item.match(/<description>(.*?)<\/description>/s);
    const dateM = item.match(/<pubDate>(.*?)<\/pubDate>/s);
    const title = (titleM && titleM[1] ? titleM[1] : '').replace(/<[^>]+>/g,'').trim();
    const url = (linkM && linkM[1] ? linkM[1] : '').trim();
    const excerpt = (descM && descM[1] ? descM[1] : '').replace(/<[^>]+>/g,'').trim().slice(0,400);
    const pubDate = dateM ? new Date(dateM[1].trim()).toISOString() : '';
    const text = (title + ' ' + excerpt).toLowerCase();
    if (title && url && isRecent(pubDate) && text.includes(kw0)) {
      items.push({ title, url, excerpt, source: 'HuggingFace', published_at: pubDate, source_weight: 85, engagement: 0 });
    }
  });
} catch(e) { console.log('HF err:', e.message); }

// --- DEDUPLICATE ---
const seen = new Set();
const deduped = items.filter(i => {
  if (!i.url || seen.has(i.url)) return false;
  seen.add(i.url);
  return true;
});

// --- KEYWORD FILTER ---
const kws = keyword.split(' ');
const relevant = deduped.filter(i => {
  const text = (i.title + ' ' + i.excerpt).toLowerCase();
  return kws.some(kw => text.includes(kw));
});

console.log('Items after dedup+filter: ' + relevant.length);

if (relevant.length === 0) {
  return [{ json: { __empty: true, keyword: config.keyword, now_display: config.now_display } }];
}

return relevant.map(i => ({ json: Object.assign({}, i, { keyword: config.keyword, now_display: config.now_display }) }));

const items = $input.all();
const outputItems = [];

for (const item of items) {
  // 1. DEBUG: Let's see what the actual structure looks like
  console.log("Full Item JSON:", JSON.stringify(item.json, null, 2));

  // 2. Try multiple possible locations for the content
  // Location A: Standard OpenAI format (choices -> message -> content)
  let rawContent = item.json.choices?.[0]?.message?.content;

  // Location B: Some nodes put it directly in 'content' or 'output'
  if (!rawContent) rawContent = item.json.content;

  // Location C: If the Groq node returns the JSON object directly in 'output'
  if (!rawContent) rawContent = item.json.output;

  let jsonData = {};

  if (!rawContent) {
    console.log("WARNING: No content found in any expected location!");
    outputItems.push({
      json: {
        title: "No content received",
        summary: "",
        score: 0,
        source: item.json.source || "Unknown",
        link: item.json.link || item.json.url || ""
      }
    });
    continue;
  }

  try {
    // 3. Clean and Parse
    let cleanContent = rawContent.trim();

    // Remove markdown if present
    if (cleanContent.startsWith('```json')) {
      cleanContent = cleanContent.replace(/^```json\s*\n/, '').replace(/\n```$/, '');
    } else if (cleanContent.startsWith('```')) {
      cleanContent = cleanContent.replace(/^```\s*\n/, '').replace(/\n```$/, '');
    }

    const parsed = JSON.parse(cleanContent);

    jsonData = {
      title: parsed.title || "Untitled",
      summary: parsed.summary || "No summary available.",
      score: parsed.score || 0,
      source: parsed.source || item.json.source || "Unknown",
      link: parsed.link || item.json.link || item.json.url || "#"
    };

  } catch (e) {
    console.error("Parse Error:", e);
    console.log("Raw content that failed:", rawContent);
    outputItems.push({
      json: {
        title: "Parse Error",
        summary: "Could not parse AI response.",
        score: 0,
        source: item.json.source || "Unknown",
        link: item.json.url || ""
      }
    });
  }

  outputItems.push({ json: jsonData });
}

return outputItems;

const items = $input.all();
if (!items || items.length === 0) return [];

const keyword = (items[0] && items[0].json.keyword ? items[0].json.keyword : '').toLowerCase();
const now = Date.now();

const scored = items.map(item => {
  const j = item.json;
  let score = j.source_weight || 50;

  // 1. Recency Score (with safety check)
  let ageHrs = 999; // Default to old if date is missing
  const pubTime = new Date(j.published_at).getTime();
  if (!isNaN(pubTime)) {
    ageHrs = (now - pubTime) / 3600000;
  }

  if (ageHrs <= 3) score += 20;
  else if (ageHrs <= 6) score += 15;
  else if (ageHrs <= 12) score += 10;
  else if (ageHrs <= 18) score += 5;

  // 2. Keyword Score
  const titleLower = (j.title || '').toLowerCase();
  const keywords = keyword.split(' ').filter(k => k.length > 0);

  // Check full phrase first (if keyword has multiple words)
  if (keyword.length > 0 && titleLower.includes(keyword)) {
    score += 15;
  }

  // Check individual words
  keywords.forEach(kw => { 
    if (titleLower.includes(kw)) score += 8; 
  });

  // 3. Engagement Score
  const eng = Math.min(j.engagement || 0, 10000);
  score += Math.floor((eng / 10000) * 20);

  // Cap score
  const finalScore = Math.min(score, 150);

  return { json: Object.assign({}, j, { score: finalScore, age_hours: parseFloat(ageHrs.toFixed(2)) }) };
});

// Sort Descending
scored.sort((a, b) => b.json.score - a.json.score);

// DEBUG: Log top 3 items to verify scoring logic
console.log('--- SCORING DEBUG ---');
console.log('Keyword:', keyword);
console.log('Total items processed:', items.length);

if (scored.length > 0) {
  const topItem = scored[0].json;
  const safeTitle = topItem.title ? String(topItem.title).substring(0, 40) : '(No Title)';

  console.log('Top Item:', {
    title: safeTitle,
    source: topItem.source || 'Unknown',
    score: topItem.score,
    age_hours: topItem.age_hours,
    raw_title_type: typeof topItem.title
  });
} else {
  console.log('No items to score after processing.');
}

return scored.slice(0, 20);

